-- Carga de 30/10/2026: conciliação SPOT DPSP e D1000 x hub.
-- Fontes: docs/cliente/2026-10-26-retorno-conciliacao-spot-dpsp.md e
-- docs/cliente/2026-10-30-pendencias-conciliacao-spot-{dpsp,d1000}-respondido.md.
-- Atômico: cada mudança exige a obra no estado lido antes (1 linha), senão aborta tudo.
do $$
declare
  n int; r record;
  qm text := 'carga-30-10 (Claude, a pedido do Jose Guilherme)';
  mo jsonb := '{"a":"Conciliação SPOT DPSP: retorno do time em 25-26/10","b":"Conciliação SPOT DPSP: resposta do Gabriel em 28/10","c":"Conciliação SPOT D1000: resposta do time em 28/10","d":"Conciliação SPOT D1000: lista conferida pelo time (planilha respondida em 28/10)"}';
  nm jsonb := '{"definir":"Aguardando definição","levantamento":"Levantamento","andamento":"Em andamento","paralisado":"Paralisado","relatorio":"Relatório de entrega","aprovarOS":"Executado - pendente aprovação OS","fecharOS":"Fechar OS","pendFat":"Pendente faturamento","faturado":"Faturado","cancelado":"Cancelada"}';
begin
  -- 1. Troca de etapa: (os, de, para, motivo, limpa marcos)
  for r in select * from (values
    ('0726-018834','levantamento','aprovarOS','a',''), ('0726-018624','levantamento','aprovarOS','a',''),
    ('0726-018710','levantamento','aprovarOS','a',''), ('0726-018684','levantamento','aprovarOS','a',''),
    ('0726-018167','levantamento','aprovarOS','a',''), ('1026-007526','levantamento','aprovarOS','a',''),
    ('0726-019042','levantamento','aprovarOS','a',''), ('1026-007527','levantamento','aprovarOS','a',''),
    ('0726-018718','levantamento','aprovarOS','a',''), ('1026-007529','levantamento','aprovarOS','a',''),
    ('0826-014414','levantamento','aprovarOS','a',''), ('0926-016516','levantamento','aprovarOS','a',''),
    ('0926-017453','levantamento','aprovarOS','a',''), ('1026-006468','levantamento','aprovarOS','a',''),
    ('0926-018266','levantamento','aprovarOS','a',''), ('0926-019566','levantamento','aprovarOS','a',''),
    ('0926-019021','andamento','aprovarOS','a',''), ('1026-006374','andamento','aprovarOS','a',''),
    ('1026-010939','paralisado','aprovarOS','a',''), ('0726-017515','levantamento','aprovarOS','a',''),
    ('0726-017988','levantamento','aprovarOS','b',''),
    ('1026-007537','levantamento','fecharOS','b',''), ('0726-018381','levantamento','fecharOS','b',''),
    ('0726-018233','aprovarOS','pendFat','b',''),
    ('0926-014254','fecharOS','aprovarOS','a','os_aprov'), ('0826-014902','fecharOS','aprovarOS','a','os_aprov'),
    ('1026-005630','aprovarOS','levantamento','a','exec')
  ) v(os, de, para, m, limpa) loop
    update obras_obra set etapa = r.para, etapa_por = qm, etapa_em = now(), desde_etapa = current_date, atualizacao = current_date,
      marco_os_aprov = case when r.limpa = 'os_aprov' then null else marco_os_aprov end,
      marco_exec_fim = case when r.limpa = 'exec' then null else marco_exec_fim end,
      marco_relatorio = case when r.limpa = 'exec' then null else marco_relatorio end
    where os = r.os and etapa = r.de;
    get diagnostics n = row_count; if n <> 1 then raise exception 'carga: % linhas em % %>%', n, r.os, r.de, r.para; end if;
    insert into obras_historico (obra_id, bloco, campo, de, para, motivo, quem)
      select id, 'Esteira', 'etapa', nm->>r.de, nm->>r.para, mo->>r.m, qm from obras_obra where os = r.os;
  end loop;

  -- 2. Descancelar 0726-018976 (executada e aprovada no desk, não é duplicata) e levar a Fechar OS
  update obras_obra set etapa = 'paralisado', cancelado_por = null, cancelado_obs = null, cancelado_em = null, cancelado_quem = null, cancelado_etapa_anterior = null
    where os = '0726-018976' and etapa = 'cancelado' and cancelado_etapa_anterior = 'paralisado';
  get diagnostics n = row_count; if n <> 1 then raise exception 'carga: 0726-018976 descancelar'; end if;
  update obras_obra set etapa = 'fecharOS', etapa_por = qm, etapa_em = now(), desde_etapa = current_date, atualizacao = current_date where os = '0726-018976';
  insert into obras_historico (obra_id, bloco, campo, de, para, motivo, quem)
    select id, 'Cancelamento', 'etapa', 'Cancelada', 'Fechar OS', (mo->>'b') || ': executada e aprovada no desk, não é duplicata', qm from obras_obra where os = '0726-018976';

  -- 3. Cancelamentos: (os, etapa atual, motivo). O check só deixa cancelar a partir de etapa de campo;
  --    fora delas passa por "Em andamento", como o time faz na tela (OS 772 em 28/10).
  for r in select * from (values
    ('0526-014042','paralisado','a: cancelar'), ('0926-011789','levantamento','a: cancelar'), ('1026-005755','andamento','a: cancelar'),
    ('0826-014968','faturado','a: cancelar'), ('385','aprovarOS','a: duplicata da 0826-006870'),
    ('572','aprovarOS','a: duplicata da 0826-004109'), ('609','aprovarOS','b: duplicata da 0826-008943'),
    ('DP ITABORAI - ILUMINAÇÃO NO ESTOQUE','pendFat','a: duplicata da 0626-008723')
  ) v(os, de, m) loop
    if r.de not in ('definir','levantamento','andamento','paralisado') then
      update obras_obra set etapa = 'andamento' where os = r.os and etapa = r.de;
      get diagnostics n = row_count; if n <> 1 then raise exception 'carga: % linhas em % %>andamento', n, r.os, r.de; end if;
    end if;
    update obras_obra set etapa = 'cancelado', cancelado_por = 'manfac', cancelado_em = now(), cancelado_quem = qm,
      cancelado_obs = (mo->>left(r.m,1)) || substr(r.m,2) || case when r.de not in ('definir','levantamento','andamento','paralisado') then ' (estava em ' || (nm->>r.de) || ')' else '' end,
      cancelado_etapa_anterior = case when r.de in ('definir','levantamento','andamento','paralisado') then r.de else 'andamento' end,
      etapa_por = qm, etapa_em = now(), desde_etapa = current_date, atualizacao = current_date
    where os = r.os and etapa = case when r.de in ('definir','levantamento','andamento','paralisado') then r.de else 'andamento' end;
    get diagnostics n = row_count; if n <> 1 then raise exception 'carga: % linhas ao cancelar %', n, r.os; end if;
    insert into obras_historico (obra_id, bloco, campo, de, para, motivo, quem)
      select id, 'Cancelamento', 'etapa', nm->>r.de, 'Cancelada', cancelado_obs, qm from obras_obra where os = r.os;
  end loop;

  -- 4. Campos: (os, coluna, de, para, motivo). Número da OS: a linha de teste libera o número antes.
  for r in select * from (values
    ('0926-017378','os','0926-017378','TESTE 0926-017378','a'),
    ('367','os','367','0926-017378','a'),
    ('DP CATETE 5 - PINTURA HUB','os','DP CATETE 5 - PINTURA HUB','0626-010287','a'),
    ('DP RECREIO 10 - FORRO VENTANIA','os','DP RECREIO 10 - FORRO VENTANIA','0726-018372','a'),
    ('0726-017988','valor','1105.47','722.45','b'),
    ('0826-008943','valor','1185.65','1185.64','b'),
    ('0926-014997','valor',null,'896.98','a: valor do desk'),
    ('3230485','loja','TMO-185','TMO-186','c'),
    ('3263792','valor','3079.66','2107.23','c')
  ) v(os, col, de, para, m) loop
    if r.col = 'os' then
      update obras_obra set os = r.para, atualizacao = current_date where os = r.os;
    elsif r.col = 'loja' then
      update obras_obra set loja = r.para, atualizacao = current_date where os = r.os and loja = r.de;
    else
      update obras_obra set valor = r.para::numeric, atualizacao = current_date where os = r.os and valor is not distinct from r.de::numeric;
    end if;
    get diagnostics n = row_count; if n <> 1 then raise exception 'carga: % linhas em % %', n, r.os, r.col; end if;
    -- obras_historico_campo_check não aceita 'os' nem 'loja' (a sync troca o número sem histórico);
    -- essas trocas ficam registradas só neste arquivo
    if r.col = 'valor' then
      insert into obras_historico (obra_id, bloco, campo, de, para, motivo, quem)
        select id, 'Identificação', 'valor',
          case when r.de is not null then 'R$ ' || replace(replace(replace(to_char(r.de::numeric,'FM999,999,990.00'),',','X'),'.',','),'X','.') end,
          'R$ ' || replace(replace(replace(to_char(r.para::numeric,'FM999,999,990.00'),',','X'),'.',','),'X','.'),
          (mo->>left(r.m,1)) || substr(r.m,2), qm
        from obras_obra where os = r.os;
    end if;
  end loop;

  -- 5. 0226-005730: não é duplicata; faturada em 20/08 (pedido e folhas informados pelo Gabriel)
  update obras_obra set etapa = 'faturado', etapa_por = qm, etapa_em = now(), desde_etapa = current_date, atualizacao = current_date,
    fat_pedido = '4500716175', fat_folhas = '1000687050 / 1000687051', marco_faturou = '2026-08-20'
  where os = '0226-005730' and etapa = 'pendFat';
  get diagnostics n = row_count; if n <> 1 then raise exception 'carga: 0226-005730 faturar'; end if;
  insert into obras_historico (obra_id, bloco, campo, de, para, motivo, quem)
    select id, 'Esteira', 'etapa', 'Pendente faturamento', 'Faturado', (mo->>'b') || ': não é duplicata; faturada em 20/08, pedido 4500716175', qm from obras_obra where os = '0226-005730';

  -- 6. Obras novas: [os, cliente, loja, descrição, valor, analista, etapa, motivo, mau uso, aprovação, OS aprovada, fim da execução, relatório]
  with src as (
    select e->>0 os, e->>1 cl, e->>2 lj, e->>3 ds, (e->>4)::numeric v, e->>5 an, e->>6 et,
      (mo->>left(e->>7,1)) || substr(e->>7,2) mt, (e->>8)::boolean mu, (e->>9)::date ap, (e->>10)::boolean oa, (e->>11)::date ex, (e->>12)::date re
    from jsonb_array_elements('[["0526-019295","DPSP","DP BARRA DA TIJUCA 5","Solicito desentupimento do esgoto e caixas de gordura, água retornando pra loja",4791.2,"LEANDRO","pendFat","a",false,null,true,null,null],["0626-003845","DPSP","DP RIO BRANCO 2","A Porta 3 encontra-se desalinhada, apresentando grande dificuldade para fechamento",1300.66,"LEANDRO","pendFat","a",false,null,true,null,null],["0926-010530","DPSP","DP BARRA DA TIJUCA 4","Troca da fechadura, chave quebrada.",570,"LEANDRO","pendFat","b",false,null,true,null,null],["1026-007544","DPSP","DP HUMAITA","Transporte da geladeira e instalação de tomada (Cinta)",1005.98,"LEANDRO","pendFat","a",false,null,true,null,null],["0926-012125","DPSP","DP SHOPPING PLAZA NITEROI","Solicito um ponto de tomada na gerencia para colocar a geladeira ponto 220",1454,"AMANDA","aprovarOS","a",false,null,true,null,null],["2767867","D1000","TMO-188","SUBSTITUIÇÃO DE BOTOEIRA DA PORTA",530,"FELIPE","aprovarOS","d",false,"2026-06-23",true,"2026-06-29","2026-06-29"],["2866916","D1000","TMO-193","REPARO DA MAQUISE E FACHADA",3412.16,"FELIPE","aprovarOS","d",false,null,true,"2026-05-08","2026-05-08"],["2982319","D1000","TMO-142","INSTALAÇÃO DE BOMBA PRESSURUZADORA",1969.13,"FELIPE","aprovarOS","d",false,"2026-06-16",true,"2026-06-17","2026-06-17"],["3018955","D1000","DML-36","TROCA DE CENTRAL DE PORTA",1145.44,"LETICIA","aprovarOS","d",false,"2026-07-07",true,"2026-07-08","2026-07-08"],["3032545","D1000","TMO-131","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"FELIPE","aprovarOS","d",true,null,true,"2026-07-17","2026-07-17"],["3047605","D1000","TMO-139","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"FELIPE","aprovarOS","d",true,null,true,"2026-07-17","2026-07-17"],["3065960","D1000","TMO-147","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-07-15","2026-07-15"],["3072695","D1000","TMO-147","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-07-20","2026-07-20"],["3078140","D1000","TMO-137","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-07-20","2026-07-20"],["3078259","D1000","TMO-160","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-07-29","2026-07-29"],["3078536","D1000","DML-54","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"LETICIA","aprovarOS","d",true,"2026-10-14",true,"2026-07-20","2026-07-20"],["3080881","D1000","TMO-147","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-09-24","2026-09-24"],["3086866","D1000","TMO-147","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-09-24","2026-09-24"],["3099670","D1000","TMO-143","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"FELIPE","aprovarOS","d",true,null,true,"2026-09-24","2026-09-24"],["3108288","D1000","DML-25","SUBSTITUIÇÃO DE TRAVA DA PORTINHOLA",200.8,"LETICIA","aprovarOS","d",true,null,true,"2026-08-05","2026-08-05"],["3112825","D1000","DML-13","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"LETICIA","aprovarOS","d",true,null,true,"2026-08-27","2026-08-27"],["3123030","D1000","FML-67","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"LETICIA","aprovarOS","d",true,null,true,"2026-08-31","2026-08-31"],["3139237","D1000","TMO-134","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-08-13","2026-08-13"],["3147017","D1000","DML-637","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"LETICIA","aprovarOS","d",true,null,true,"2026-08-20","2026-08-20"],["3147597","D1000","DML-34","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"LETICIA","aprovarOS","d",true,null,true,"2026-08-20","2026-08-20"],["3153379","D1000","TMO-141","SUBSTITUIÇÃO DE TAMBOR POR MAU USO",200.8,"FELIPE","aprovarOS","d",true,"2026-10-14",true,"2026-09-17","2026-09-17"],["3163062","D1000","DML-77","SUBSTITUIÇÃO DE TRAVA LATERAL",200.8,"LETICIA","aprovarOS","d",true,null,true,"2026-09-15","2026-09-15"],["3167169","D1000",